class CheckoutViewModel(private val savedState: SavedStateHandle) : ViewModel() {
    var name by savedField("name")
    var email by savedField("email")
    var phone by savedField("phone")
    var address by savedField("address")
    var city by savedField("city")
    var pincode by savedField("pincode")

private fun savedField(key: String): ReadWriteProperty<Any?, String> {
    val state = mutableStateOf(savedState[key] ?: "")
    return object : ReadWriteProperty<Any?, String> {
        override fun getValue(thisRef: Any?, property: KProperty<*>) = state.value
        override fun setValue(thisRef: Any?, property: KProperty<*>, value: String) {
            state.value = value
            savedState[key] = value
        }
    }
}

